cypress_script:
describe('Product Catalogue with Sorting', () => {
  it('should display products and allow sorting', () => {
    cy.visit('https://www.saucedemo.com/inventory.html');
    cy.get('[data-test="product-sort-container"]').should('be.visible');
    cy.get('[data-test="item-0-title-link"]').should('be.visible');
    cy.get('[data-test="item-1-title-link"]').should('be.visible');
    cy.get('[data-test="item-2-title-link"]').should('be.visible');
    cy.get('[data-test="item-3-title-link"]').should('be.visible');
    cy.get('[data-test="item-4-title-link"]').should('be.visible');
    cy.get('[data-test="item-5-title-link"]').should('be.visible');
    cy.get('[data-test="product-sort-container"]').select('lohi');
    cy.get('[data-test="item-0-title-link"]').should('have.text', 'Sauce Labs Bike Light');
  });
  it('should not display products when sorting fails', () => {
    cy.visit('https://www.saucedemo.com/inventory.html');
    cy.get('[data-test="product-sort-container"]').select('invalid-option');
    cy.get('[data-test="item-0-title-link"]').should('not.exist');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Product Catalogue with Sorting', () => {
  test('should display products and allow sorting', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/inventory.html');
    await expect(page.locator('[data-test="product-sort-container"]')).toBeVisible();
    await expect(page.locator('[data-test="item-0-title-link"]')).toBeVisible();
    await expect(page.locator('[data-test="item-1-title-link"]')).toBeVisible();
    await expect(page.locator('[data-test="item-2-title-link"]')).toBeVisible();
    await expect(page.locator('[data-test="item-3-title-link"]')).toBeVisible();
    await expect(page.locator('[data-test="item-4-title-link"]')).toBeVisible();
    await expect(page.locator('[data-test="item-5-title-link"]')).toBeVisible();
    await page.selectOption('[data-test="product-sort-container"]', 'lohi');
    await expect(page.locator('[data-test="item-0-title-link"]').textContent()).toBe('Sauce Labs Bike Light');
  });
  test('should not display products when sorting fails', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/inventory.html');
    await page.selectOption('[data-test="product-sort-container"]', 'invalid-option');
    await expect(page.locator('[data-test="item-0-title-link"]').count()).toBe(0);
  });
});
